# Combine 与 Kotlin Flow

Apple Combine 和 Kotlin Flow 是各自平台的原生 FRP 实现，设计理念与 Reactive Streams 规范高度对齐，但针对各自语言特性（Swift 协议/值语义，Kotlin 协程）做了适配。

## 核心概念

**Apple Combine**（iOS 13+/macOS 10.15+）将响应式编程作为一等公民内置于 Apple 平台：

```swift
import Combine

// Publisher: 发布值序列的协议
protocol Publisher {
    associatedtype Output  // 输出值类型
    associatedtype Failure: Error  // 错误类型（Never = 不会出错）
    func receive<S: Subscriber>(subscriber: S)
        where S.Input == Output, S.Failure == Failure
}

// Subscriber: 接收值的协议
protocol Subscriber {
    associatedtype Input
    associatedtype Failure: Error
    func receive(subscription: Subscription)
    func receive(_ input: Input) -> Subscribers.Demand  // 返回需求量（背压）
    func receive(completion: Subscribers.Completion<Failure>)
}

// Cancellable: 取消订阅的协议（对应 RxJS 的 Subscription）
protocol Cancellable {
    func cancel()
}
```

Combine 的类型系统使用 Associated Types，使背压信号在编译时就能检查：`Subscribers.Demand` 是强类型的需求量，而不是整数。

**Kotlin Flow**（协程扩展库）将响应式流与协程深度整合：

```kotlin
import kotlinx.coroutines.flow.*

// Flow: 冷流（Cold），每次 collect 从头执行
fun coldFlow(): Flow<Int> = flow {
    emit(1)
    delay(100)  // 挂起函数，不阻塞线程
    emit(2)
    emit(3)
}

// suspend collect: 在协程作用域中消费
suspend fun main() {
    coldFlow().collect { value ->
        println("收到: $value")
    }
}
```

| 维度     | Combine                     | Kotlin Flow                         |
| -------- | --------------------------- | ----------------------------------- |
| 协议     | Reactive Streams 兼容       | 协程原生                            |
| 冷热流   | Publisher/Subject 系列      | Flow(冷) / SharedFlow/StateFlow(热) |
| 线程切换 | `.receive(on:)`             | `flowOn`                            |
| 背压     | `Subscribers.Demand` 强类型 | 协程挂起自然背压                    |
| 取消     | `AnyCancellable`            | 协程 `Job`                          |
| 平台     | Apple 专属                  | JVM/Android/多平台                  |

## Combine Publisher 体系

```swift
import Combine

// 内置 Publisher
let just = Just(42)                        // 发出单值后完成
let fail = Fail<Int, URLError>(error: .init(.badURL))
let empty = Empty<Int, Never>()            // 立即完成，不发值
let deferred = Deferred { Just(computeValue()) }  // 惰性创建

// Subject: 命令式桥接（对应 RxJS Subject）
let passthrough = PassthroughSubject<String, Never>()  // 无初始值
let current = CurrentValueSubject<Int, Never>(0)       // 有初始值（对应 BehaviorSubject）

// 订阅（使用 sink）
let cancellable1 = passthrough
    .sink(
        receiveCompletion: { print("完成: \($0)") },
        receiveValue:      { print("值: \($0)") }
    )

// 必须持有 AnyCancellable，否则立即取消
var cancellables = Set<AnyCancellable>()
passthrough.sink { print($0) }.store(in: &cancellables)

// 操作符链（与 RxJS 一一对应）
let result = URLSession.shared
    .dataTaskPublisher(for: url)
    .map(\.data)
    .decode(type: Response.self, decoder: JSONDecoder())
    .receive(on: DispatchQueue.main)  // 切换到主线程
    .catch { _ in Just(Response.empty) }
    .eraseToAnyPublisher()  // 擦除具体类型
```

## Combine 与 SwiftUI 集成

```swift
import SwiftUI
import Combine

// @Published: 自动包装为 Publisher
class SearchViewModel: ObservableObject {
    @Published var query: String = ""
    @Published var results: [String] = []

    private var cancellables = Set<AnyCancellable>()

    init() {
        // 搜索框防抖
        $query
            .debounce(for: .milliseconds(300), scheduler: RunLoop.main)
            .removeDuplicates()
            .filter { !$0.isEmpty }
            .flatMap { [weak self] q in
                self?.search(q) ?? Empty().eraseToAnyPublisher()
            }
            .receive(on: DispatchQueue.main)
            .sink { [weak self] results in
                self?.results = results
            }
            .store(in: &cancellables)
    }

    private func search(_ query: String) -> AnyPublisher<[String], Never> {
        URLSession.shared
            .dataTaskPublisher(for: searchURL(query))
            .map { $0.data }
            .decode(type: [String].self, decoder: JSONDecoder())
            .catch { _ in Just([]) }
            .eraseToAnyPublisher()
    }
}
```

## Kotlin Flow 冷流与热流

```kotlin
// 冷流（Cold Flow）：每次 collect 独立执行
fun coldNumbers(): Flow<Int> = flow {
    println("开始生成")
    for (i in 1..5) {
        delay(100)
        emit(i)
    }
}

// 热流（Hot Flow）：SharedFlow
val sharedFlow = MutableSharedFlow<Int>(
    replay = 2,         // 新订阅者收到最近 2 个历史值
    extraBufferCapacity = 10  // 额外缓冲
)

// SharedFlow 作为事件总线
class EventBus {
    private val _events = MutableSharedFlow<AppEvent>()
    val events = _events.asSharedFlow()

    suspend fun emit(event: AppEvent) = _events.emit(event)
}

// StateFlow（对应 BehaviorSubject / CurrentValueSubject）
val stateFlow = MutableStateFlow(0)  // 初始值 0
println(stateFlow.value)  // 同步读取当前值

// 在 ViewModel 中使用（Android）
class CounterViewModel : ViewModel() {
    private val _count = MutableStateFlow(0)
    val count: StateFlow<Int> = _count.asStateFlow()

    fun increment() { _count.value++ }
}
```

## Kotlin Flow 的线程切换：flowOn

```kotlin
// flowOn 指定 Flow 的生产端（上游）在哪个线程运行
// 消费端的线程由 collect 所在的协程决定

fun fetchData(): Flow<Data> = flow {
    // 这段代码在 IO 线程执行
    val data = database.query()  // 阻塞 I/O
    emit(data)
}
.flowOn(Dispatchers.IO)  // 上游在 IO 调度器

// collect 在 UI 线程（因为 viewModelScope 在主线程）
viewModelScope.launch {
    fetchData()
        .map { it.transform() }  // 这个 map 在哪？取决于上下文
        // flowOn 只影响它"上游"的操作符
        .flowOn(Dispatchers.Default)  // transform() 在 Default
        .collect { data ->
            // collect 在 viewModelScope 的线程（主线程）
            updateUI(data)
        }
}

// 与 RxJS observeOn/subscribeOn 的类比
// flowOn    ≈ subscribeOn（影响上游）
// withContext 在 collect 内 ≈ observeOn（影响消费）
```

## 背压对比

```swift
// Combine 的显式背压（通过 Demand）
class LimitedSubscriber: Subscriber {
    typealias Input = Int
    typealias Failure = Never

    func receive(subscription: Subscription) {
        subscription.request(.max(3))  // 只请求 3 个
    }

    func receive(_ input: Int) -> Subscribers.Demand {
        print("收到: \(input)")
        return .max(1)  // 每处理一个再请求一个
    }

    func receive(completion: Subscribers.Completion<Never>) {}
}
```

```kotlin
// Kotlin Flow 的隐式背压（协程挂起）
// 不需要显式 request()，挂起函数自然实现背压
flow {
    for (i in 1..1000) {
        emit(i)  // 如果 collect 端慢，emit 会挂起等待
    }
}
.collect { value ->
    delay(100)  // 慢消费者，但不会 OOM
    println(value)
}

// 需要缓冲时使用 buffer()
flow { ... }
    .buffer(capacity = 10)  // 生产者最多超前消费者 10 个
    .collect { ... }
```

## 小结

- **Combine** 是 Apple 平台原生响应式框架，`Publisher`/`Subscriber`/`Cancellable` 协议与 Reactive Streams 语义对齐；`AnyCancellable` 的生命周期管理是关键，必须持有引用
- **CurrentValueSubject** 对应 BehaviorSubject，`PassthroughSubject` 对应 Subject
- **Kotlin Flow** 与协程深度整合，冷流（`flow {}`）是默认；`SharedFlow`（重放/多播）和 `StateFlow`（当前值）是热流变体
- **flowOn** 声明上游生产线程，消费线程由 `collect` 所在协程决定；与 RxJS `subscribeOn` 类似
- Kotlin Flow 的背压通过协程挂起隐式实现，无需显式 `request(n)`

